test("day 0 is allowed with a full window", function () {
  assert.deepEqual(code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-01-10" }), { allowed: true, daysLeft: 120, elapsedDays: 0 });
});
test("mid-window days left", function () {
  assert.deepEqual(code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-03-10" }), { allowed: true, daysLeft: 61, elapsedDays: 59 });
});
test("day 120 is still allowed with 0 days left", function () {
  assert.deepEqual(code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-05-10" }), { allowed: true, daysLeft: 0, elapsedDays: 120 });
});
test("after day 120 the window is closed", function () {
  assert.deepEqual(code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-05-11" }), { allowed: false, daysLeft: 0, elapsedDays: 121 });
});
test("denial date counts as day 0", function () {
  assert.deepEqual(code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-01-11" }), { allowed: true, daysLeft: 119, elapsedDays: 1 });
});
test("day 119 is still inside the window", function () {
  assert.deepEqual(code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-05-09" }), { allowed: true, daysLeft: 1, elapsedDays: 119 });
});
test("days left is 0, not negative, once closed", function () {
  assert.deepEqual(code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-05-12" }), { allowed: false, daysLeft: 0, elapsedDays: 122 });
});
